77	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
