325	    private static boolean isBlank(String value) {
326	        return value == null || value.isBlank();
327	    }
328	
329	    /**
330	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
331	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
332	     * to the effective registration date (whether supplied in the request or defaulted to the server
333	     * date), so every value derived from the registration date sees the adjusted business day.
334	     */
335	    private static LocalDate toBusinessDay(LocalDate date) {
336	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
337	            date = date.plusDays(1);
338	        }
339	        return date;
340	    }
341	
342	    /**
343	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
344	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
345	     * lower-cased so that last names are compared case-insensitively.
346	     */
347	    private static String normalizeHousehold(String value) {
348	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
349	    }
350	
351	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
352	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
353	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
354	
355	    /**
356	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
357	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
358	     * upper-cased, and common street-type abbreviations are expanded token-by-token
359	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
360	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
361	     * used for every address comparison (household-duplicate detection and the shared household id).
362	     */
363	    private static String normalizeAddress(String value) {
364	        if (value == null) {
365	            return "";
366	        }
367	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
368	        if (collapsed.isEmpty()) {
369	            return "";
370	        }
371	        String[] tokens = collapsed.split(" ");
372	        StringBuilder sb = new StringBuilder();
373	        for (int i = 0; i < tokens.length; i++) {
374	            if (i > 0) {
375	                sb.append(' ');
376	            }
377	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
378	        }
379	        return sb.toString();
380	    }
381	
382	    /**
383	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
384	     * deterministic function of the normalized last name and address, so every owner that
385	     * shares those values maps to the same identifier regardless of creation order.
386	     */
387	    private static String householdId(String normalizedLastName, String normalizedAddress) {
388	        String key = normalizedLastName + "\n" + normalizedAddress;
389	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
390	    }
391	
392	    /**
393	     * Builds the {@code customerCode} assigned to a new owner, formatted
394	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
395	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
396	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
397	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
398	     */
399	    private String nextCustomerCode(String city, String lastName) {
400	        String city3 = prefix3(city);
401	        String last3 = prefix3(lastName);
402	        long sequence = this.clinicService.findAllOwners().stream()
403	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
404	            .count() + 1L;
405	        return String.format("%s-%s-%04d", city3, last3, sequence);
406	    }
407	
408	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
409	    private static String prefix3(String value) {
410	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
411	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Counts the existing owners that share the given first name and last name, compared
416	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
417	     * owner currently being created is saved), so it reflects how many namesakes preceded the
418	     * new owner.
419	     */
420	    private int countNamesakes(String firstName, String lastName) {
421	        return (int) this.clinicService.findAllOwners().stream()
422	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
423	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
424	            .count();
425	    }
426	
427	    /**
428	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
429	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
430	     * national one, a single leading {@code '0'} is dropped, and the default country code
431	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
432	     * national number must have the length required by its country code ({@code '+61'} requires 9
433	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
434	     * raised (reported to the client as 400).
435	     */
436	    private static String toE164(String telephone) {
437	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
438	        String digits;
439	        if (cleaned.startsWith("+")) {
440	            digits = cleaned.substring(1);
441	        } else {
442	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
443	            digits = "61" + national;
444	        }
445	        if (!digits.matches("[0-9]{8,15}")) {
446	            throw new InvalidTelephoneException(
447	                "telephone must form a valid E.164 number with 8 to 15 digits");
448	        }
449	        validateNationalLength(digits);
450	        return "+" + digits;
451	    }
452	
453	    /** National-number length required for each supported country code (digits after the code). */
454	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
455	        "61", 9, "1", 10);
456	
457	    /**
458	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
459	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
460	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
461	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
462	     */
463	    private static void validateNationalLength(String digits) {
464	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
465	            String code = entry.getKey();
466	            if (digits.startsWith(code)) {
467	                int nationalLength = digits.length() - code.length();
468	                if (nationalLength != entry.getValue()) {
469	                    throw new InvalidTelephoneException(
470	                        "telephone national number must have " + entry.getValue()
471	                            + " digits for country code +" + code);
472	                }
473	                return;
474	            }
475	        }
476	    }
477	
478	    /**
479	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
480	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
481	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
482	     * stored and returned in canonical form.
483	     */
484	    private static String normalizeEmail(String email) {
485	        if (isBlank(email)) {
486	            return null;
487	        }
488	        String trimmed = email.trim();
489	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
490	            throw new InvalidEmailException("email must be a syntactically valid address");
491	        }
492	        return trimmed.toLowerCase(Locale.ROOT);
