15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class, imports = LocalityDeriver.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "membershipNumber",
27	        expression = "java(owner.getCustomerCode() + \"-M\" "
28	            + "+ String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
29	    @Mapping(target = "membershipLevel",
30	        expression = "java(Math.min(3, 1 "
31	            + "+ ((owner.getEmail() != null && !owner.getEmail().isBlank()) ? 1 : 0) "
32	            + "+ ((owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) ? 1 : 0)))")
33	    @Mapping(target = "locality", expression = "java(LocalityDeriver.locality(owner.getCity()))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    Owner toOwner(OwnerDto ownerDto);
37	
38	    @Mapping(target = "id", ignore = true)
39	    @Mapping(target = "pets", ignore = true)
40	    Owner toOwner(OwnerFieldsDto ownerDto);
41	
42	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
43	
44	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
45	
46	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
47	        OwnerPageDto ownerPageDto = new OwnerPageDto();
48	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
49	        ownerPageDto.setPage(ownerPage.getNumber());
50	        ownerPageDto.setSize(ownerPage.getSize());
